CREATE OR REPLACE FUNCTION public.lock_invoice_number() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.company_id::text||NEW.kind||lower(regexp_replace(NEW.number,'\s','','g')),0)); RETURN NEW; END $$;
CREATE TRIGGER a_lock_invoice_number BEFORE INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.lock_invoice_number();
CREATE OR REPLACE FUNCTION public.require_invoice_totals() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE j jsonb; BEGIN j:=NEW.invoice_details; IF j->>'version'='2' THEN IF j->>'mode' IS NULL OR j->>'currency' IS NULL OR j->>'number' IS NULL OR j->>'issueDate' IS NULL OR jsonb_typeof(j->'lines') IS DISTINCT FROM 'array' OR j->>'net' IS NULL OR j->>'vat' IS NULL OR j->>'total' IS NULL THEN RAISE EXCEPTION 'Completează datele și totalurile facturii.'; END IF; IF length(coalesce(j->>'number',''))>100 OR length(coalesce(j->>'series',''))>100 THEN RAISE EXCEPTION 'Numărul sau seria sunt prea lungi.'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER b_require_invoice_totals BEFORE INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.require_invoice_totals();